self.KB_CONTENT["card:779679"]={"id":"card:779679","ty":"card","sourceId":"779679","title":"『進貨單驗收作業(IDL)』的作業重點有哪些？","ver":"GP4以上","topic":"進貨單","keywords":["進貨單","驗收"],"y":"explain","answer":"■作業重點1. 只可執行 \"查詢\"、\"修改\"、\"列印\"。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
