self.KB_CONTENT["card:780099"]={"id":"card:780099","ty":"card","sourceId":"780099","title":"『生產入庫檢驗單憑證』中的『選擇檢驗狀態 (MOC.TG016)』為何？","ver":"GP4以上","topic":"憑證","keywords":["憑證","生產","狀態","入庫"],"y":"other","answer":"* 分為1.待驗、2.合格、3.不良、4.特採及9.全部五種檢驗狀態。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
