self.KB_CONTENT["card:779770"]={"id":"card:779770","ty":"card","sourceId":"779770","title":"『委外工單開立』中的『發料量 (TH011)』為何？","ver":"GP4以上","topic":"製令","keywords":["製令","單身","工單","開立"],"y":"other","answer":"* 表此製令工單發料之數量。* 會由子單身重算回寫，但可以修改* 存檔時需檢查不可小於等於0。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
