self.KB_CONTENT["card:780428"]={"id":"card:780428","ty":"card","sourceId":"780428","title":"『IPSR17 預付購料費用明細表』中的『選擇課稅別 (IPS.TM011)』為何？","ver":"GP4以上","topic":"明細表","keywords":["明細表","課稅別","費用","預付"],"y":"other","answer":"* 區分為1.應稅內含、2.應稅外加、3.零稅率、4.免稅、9.不計稅及A.全部。進階選項","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
