self.KB_CONTENT["card:776991"]={"id":"card:776991","ty":"card","sourceId":"776991","title":"『多角貿易基本資料拋轉』中的『拋轉客戶資料 (C1)』為何？","ver":"GP4以上","topic":"多角貿易","keywords":["多角貿易","客戶","拋轉","清除"],"y":"other","answer":"* 預設N。* 拋轉客戶資料=Y， [起迄客戶代號] 欄位才可輸入且不可空白。* 拋轉客戶資料=N，則清除 [客戶代號] 欄位資料且不可輸入。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
