self.KB_CONTENT["card:793183"]={"id":"card:793183","ty":"card","sourceId":"793183","title":"『貨運通知單建立作業』的作業目的為何？","ver":"GP4以上","topic":"其他","keywords":[],"y":"explain","answer":"貨品輸出前確定船期、航次後，可利用此作業輸入之。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
